import{_ as a,a0 as r,w as l,s as d,ao as o,I as s,x as n,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"Linux下NTFS分區的修復和恢復 | LCTT x X-CMD","titleTemplate":false,"description":"Linux下NTFS分區的修復和恢復 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux下NTFS分區的修復和恢復 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux下NTFS分區的修復和恢復 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/NTFS Partition Repair and Recovery In Linux","title":"Linux下NTFS分區的修復和恢復","tag":"201310","desc":""},"relativePath":"201310/NTFS Partition Repair and Recovery In Linux.md","filePath":"[post].md"}'),u={name:"201310/NTFS Partition Repair and Recovery In Linux.md"};function T(x,t,f,m,S,L){const e=r("Link");return l(),d("div",null,[t[14]||(t[14]=o(`<h1 id="linux下ntfs分區的修復和恢復" tabindex="-1">Linux下NTFS分區的修復和恢復 <a class="header-anchor" href="#linux下ntfs分區的修復和恢復" aria-label="Permalink to “Linux下NTFS分區的修復和恢復”">​</a></h1><p>我們時不時需要幫助我們的朋友、家人、熟人、商業夥伴或者其他雜七雜八的人擺脱使用Windows的時候遇到的困境。儘管我們不像他們一樣日常遇到各種問題，卻經常是在他們有難的時候會求助的人。此外,甚至我們自己的Windows分區/驅動器也會出現問題（畢竟，有時候我們還是需要玩兒會兒遊戲，而且，儘管Steam在努力，但Linux還不是遊戲玩家的夢想之地），但願不會如此。下面讓我們看一兩個我們可能會遇到的狀況，那時我們可以用手邊的Linux環境和一些NTFS分區恢復工具來修復它們。</p><p>###簡單修復</p><p>Windows 系統通常能很好的處理異常的“冷重啓”（斷電，關閉插線板的電源，或家裏的小人兒手指隨意按導致關機)。事實上，至今為止，最有效的修復Windows桌面問題的方法就是簡單的重啓系統。但是，Windows分區偶爾會顯示系統需要進行驅動器一致性檢測。不這麼做的話，在幾次重啓後可能會引起文件系統狀況惡化而使系統變得更糟。眾所周知，Windows文件系統檢查超級慢，而且經常不得不做好幾次才能清理掉文件系統的“髒（dirty）”標誌。</p><p>下面介紹一個叫“ntfsfix”的小工具，在基於Debian的系統（如 Ubuntu）可以通過下面的命令下載：</p><pre><code>sudo apt-get install ntfsfix
</code></pre><p>或者在基於RPM的系統（如 Red Hat 或 CentOS）中通過下面的命令下載:</p><pre><code>sudo yum install ntfsfix
</code></pre><p>這個‘ntfsfix’工具能快速的修復常見的錯誤以及NTFS分區不一致的問題。最常用的命令不用帶任何參數。 它也可以報出來那些沒有修復掉的項，然後我們能通過以下選項來修復它們：</p><ul><li>-b: 清除磁盤上的壞的扇區 (可以在從一箇舊磁盤往新的磁盤上克隆之後使用)</li><li>-d: 清除“髒”標誌。“髒”標誌是Linux不能掛載一個Windows分區的最常見的原因，通常發生在Windows斷電前沒有正常關機的情況。</li><li>-n: 除了在標準輸出上顯示它要完成的(換句話説，就是需要修復哪些)之外不做任何事。</li></ul><p>過去Windows在啓動前，用NTFS Disk Check來重置“髒”標誌，常常要花幾個小時。而‘ntfsfix’完成這個僅僅只需要大約三秒的時。</p><p>###深度修復</p><p>不幸的是, 並非所有的問題都能被快速修復。事實上，有非常多的昂貴的磁盤恢復軟件（通常屬於“磁盤取證”類的軟件，因為是在篩選損壞磁盤的時候調查人員使用的）用來修復那些加電但不能啓動或者不能訪問文件系統的磁盤。</p>`,13)),s("p",null,[t[1]||(t[1]=n("有一個神奇的工具，免費而強大（而且如果在你本地電腦使用的話，可以放到一個可引導的救援Live CD裏面）可以用來恢復你的Windows NTFS分區（而且，也能恢復EXT2/3/4，FAT/FAT32、exFAT、HFS和SunFS文件系統）。這個工具叫做",-1)),i(e,{href:"http://www.cgsecurity.org/wiki/TestDisk"},{default:p(()=>[...t[0]||(t[0]=[n("TestDisk",-1)])]),_:1}),t[2]||(t[2]=n("，在Debian和CentOS 的軟件倉庫中可用。Red Hat的軟件倉庫中並沒有這個軟件，但是安裝它很容易。",-1))]),t[15]||(t[15]=o(`<pre><code>sudo apt-get install testdisk
</code></pre><p>在基於 RPM 的系統（如 Red Hat 或 CentOS）：</p><pre><code>sudo yum install testdisk
</code></pre><p>這個工具簡直無與倫比。如果驅動器加電並且運轉了，甚至當驅動器有物理損壞時，這個小工具仍會奇蹟般的取出一些文件來。 你可以通過一箇舊式風格的命令“sudo testdisk /dev/sdX”來啓動它，這裏‘X’是你的驅動器號，之後你會看到下面的界面：</p><p><img src="http://blog.linuxacademy.com/wp-content/uploads/2013/08/testdisk2.jpg" alt=""></p><p><em>TestDisk在終端中運行</em></p><p>這個工具使用起來很簡單，只需要根據菜單提示進行操作，而且它是交互式的。它會掃描你指定的某個分區，然後把重建的目錄和文件顯示出來，然後你可以標記，並存到另外一磁盤或者分區裏面。我已經成功地從Windows，OSX和linux分區裏面恢復過文件，這些分區要麼因為這種或那種原因不能啓動，要麼害怕啓動之後可能徹底完蛋，總之，這些分區用不了多久就會徹底完蛋了。</p><p>説句實在的，你不能期望文件系統100%的恢復，尤其是你的驅動器已經有損壞了，不過至少聊勝於無吧，而且不用像去請專業人員處理那樣花很多錢（實際上一分也不用花）。所以如果你的驅動器現在有問題了，那你可以用下這個工具。</p><p>###結束語</p><p>當你使用Linux的時候，磁盤修復要容易得多，當然也便宜的多，要麼用USB轉接器連接有問題的磁盤，要麼從一個LiveCD啓動，然後用CD裏面的修復工具。本文中我們談到的所有的工具都是免費使用，而且是在持續開發（更新）中。您可以在下面留言，談一下你曾經不得不使用什麼工具來從您磁盤的問題中恢復。</p><hr>`,11)),s("p",null,[t[4]||(t[4]=n("via: ",-1)),i(e,{href:"http://blog.linuxacademy.com/linux/ntfs-partition-repair-and-recovery-in-linux/"},{default:p(()=>[...t[3]||(t[3]=[n("http://blog.linuxacademy.com/linux/ntfs-partition-repair-and-recovery-in-linux/",-1)])]),_:1})]),s("p",null,[t[7]||(t[7]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[5]||(t[5]=[n("LCTT",-1)])]),_:1}),t[8]||(t[8]=n(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/portal.php"},{default:p(()=>[...t[6]||(t[6]=[n("Linux中國",-1)])]),_:1}),t[9]||(t[9]=n(" 榮譽推出",-1))]),s("p",null,[t[12]||(t[12]=n("譯者：",-1)),i(e,{href:"http://linux.cn/space/younel0925"},{default:p(()=>[...t[10]||(t[10]=[n("younel0925",-1)])]),_:1}),t[13]||(t[13]=n(" 校對：",-1)),i(e,{href:"http://linux.cn/space/jasminepeng"},{default:p(()=>[...t[11]||(t[11]=[n("jasminepeng",-1)])]),_:1})])])}const w=a(u,[["render",T]]);export{F as __pageData,w as default};
